  String clean(String v)=>v.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]'),'');
  String find(Map<String,dynamic> row,List<String> keys){for(final key in keys){final v='${row[key]??''}'.trim();if(v.isNotEmpty)return v;}final names=keys.map(clean).toSet();for(final e in row.entries){final v='${e.value??''}'.trim();if(names.contains(clean(e.key))&&v.isNotEmpty)return v;}return '';}
  bool sameTier(String value){if(value.trim().isEmpty)return true;final a=clean(tier),b=clean(value);return a==b||b==a.replaceFirst('tier','')||'tier$b'==a;}
