ng=false);}}
  void msg(String value)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(value)));InputDecoration decoration(String label)=>InputDecoration(labelText:label,border:OutlineInputBorder(borderRadius:BorderRadius.circular(12)));
