n(Icons.my_location_rounded),label:Text(getting?'Akurasi ${accuracy?.toStringAsFixed(1)??'-'} m':gps?.coordinate??'Ambil Koordinat Temuan')),const SizedBox(height:14),Row(children:[Expanded(child:photoBox('Foto Temuan',foto,()=>capture(true))),const SizedBox(width:10),Expanded(child:photoBox('Foto Lingkungan',lingkungan,()=>capture(false)))])]))),SafeArea(minimum:const EdgeInsets.all(18),child:SizedBox(width:double.infinity,height:50,child:ElevatedButton(onPressed:saving?null:save,child:Text(saving?'Menyimpan...':'Simpan Temuan'))))])));
